import React, { useState, useEffect } from "react";
import About1 from "./About1.jpg";
import About2 from "./About2.jpg";
import Purple from "./Purple.png";
import Footer from "./Footer";

function Invitational() {
  	return (
		<div className="home">
			<div className="first-section">
				<div className="section-title">
				<div style={{ zIndex: 1 }}>
					<h1>
					2026 Invitational
					</h1>
					<hr class="solid"/>
					<p>
					Our fifth annual Northwestern Invitational will take place in-person at our Evanston campus on February 21st, 2026. 
					</p>
				</div>
				</div>
			</div>
			<div className="first-section">
				<div className="second-section">
				<div style={{ zIndex: 1 }}>
					<h1>
					Registration
					</h1>
					<hr class="solid"/>
					<p
					style={{
						marginTop: "50px"
					}}
					>
					Registration for this tournament has closed.
					</p>
					<div
					style={{
						display: "flex",
						flexDirection: "row",
						marginTop: "50px"
					}}
				>
					<a href={'https://scilympiad.com/il-nu'}>
						<div className="button" style={{ marginRight: "50px", marginBottom: "25px" }}>
							SCILYMPIAD
						</div>
					</a>
				</div>
				</div>
				</div>
			</div>
		</div> 
	);
}

export default Invitational;
